code.css:
.vp { margin: 0; }
.vp__video { width: 100%; aspect-ratio: 16 / 9; display: block; background: #121212; border-radius: 8px; }
.vp__caption { margin-top: 8px; font-size: 12px; line-height: 16px; color: var(--color-text-secondary, #404040); }
.vp__caption a { color: #1d4ed8; }
.vp a:focus-visible, .vp video:focus-visible { outline: 2px solid #1d4ed8; outline-offset: 2px; }
